def number_2Dlist(df=None, cols=None,
                  print_out=False, print_port=print):
    n = df[cols[0]].shape[0]
    res = []
    for i in range(n):
        r = []
        for col in cols:
            try:
                _ = float(df[col].iloc[i])
                if _ > 0 or _ <= 0:
                    r.append(_)
            except BaseException:
                pass
        if len(r) == len(cols):
            res.append(r)
    if print_out:
        print = print_port
        print("Received %d cols of data. Found %d rows valid." % (
            len(cols), len(res)))
    return transpose_2D_list(res)

